import json

alphabet = [
    "f", "w", "p", "h", "s", "m", "n", "g", "y", "j", "r", "a", "x",
    "b", "z", "d", "i", "c", "q", "t", "e", "u", "o", "v", "k", "l"
]
words = [
    "highwaymen", "boyish", "antidisestablishmentarianism", "publications",
    "cutlet", "muscular", "musky", "leather", "synaptic", "paula", "astigmat",
    "zinc", "demonstrations", "godson", "creak", "heaven", "easternmost",
    "coriolanus", "scavenge", "individualization", "telecommunications"
]

rank = {letter: index for index, letter in enumerate(alphabet)}
keys = {word: tuple(rank[letter] for letter in word) for word in words}
ordered = sorted(words, key=keys.__getitem__)

print(json.dumps({
    "final_answer": ", ".join(ordered),
    "evidence": {
        "alphabet": "".join(alphabet),
        "sorted_rank_sequences": [
            [word, list(keys[word])] for word in ordered
        ]
    }
}, separators=(",", ":")))
